  variants: {
    variant: {
      default:
        "bg-primary text-primary-foreground shadow-[var(--shadow-card)] hover:bg-primary/90 pressed:bg-primary/90",
      secondary:
        "bg-secondary text-secondary-foreground hover:bg-border/70 pressed:bg-border/70",
      outline:
        "border border-border bg-card text-foreground shadow-[var(--shadow-card)] hover:bg-muted pressed:bg-muted",
      ghost:
        "text-foreground hover:bg-muted in-data-[item-highlight=under]:hover:bg-transparent pressed:bg-muted aria-[pressed=true]:bg-accent aria-[pressed=true]:text-accent-foreground aria-[pressed=true]:hover:bg-accent",
      minimal:
        "text-muted-foreground hover:bg-muted in-data-[item-highlight=under]:hover:bg-transparent hover:text-foreground pressed:bg-muted pressed:text-foreground",
      destructive:
        "bg-destructive text-background shadow-[var(--shadow-card)] hover:bg-destructive/90 pressed:bg-destructive/90",
    },
    size: {
      xs: `h-7 gap-1.5 rounded-sm px-2.5 text-xs [&_svg:not([class*='size-'])]:size-3.5 ${touchTarget}`,
      sm: `h-9 gap-2 px-3.5 text-sm [&_svg:not([class*='size-'])]:size-4 ${touchTarget}`,
      md: "h-11 gap-2 px-5 text-sm [&_svg:not([class*='size-'])]:size-4",
      lg: "h-12 gap-2 px-6 text-sm [&_svg:not([class*='size-'])]:size-4",
      xl: "h-14 gap-2.5 rounded-lg px-7 text-base [&_svg:not([class*='size-'])]:size-5",
    },
    iconOnly: {
      true: "cursor-pointer px-0",
    },
  },
  compoundVariants: [
    { size: "xs", iconOnly: true, class: "w-7" },
    { size: "sm", iconOnly: true, class: "w-9" },
    {
      size: "md",
      iconOnly: true,
      class: "w-11 [&_svg:not([class*='size-'])]:size-4.5",
    },
    {
      size: "lg",
      iconOnly: true,
      class: "w-12 [&_svg:not([class*='size-'])]:size-5",
    },
    {
      size: "xl",
      iconOnly: true,
      class: "w-14 [&_svg:not([class*='size-'])]:size-6",
    },
  ],
  defaultVariants: { variant: "default", size: "md" },
});

export const buttonLinkStyles = tv({
  extend: buttonStyles,
  base: "cursor-pointer",
});

export type ButtonVariant = NonNullable<
  VariantProps<typeof buttonStyles>["variant"]
>;

"use client";

import { motion, useReducedMotion } from "motion/react";
import { useContext } from "react";
import {
  ToggleButton as AriaToggleButton,
  composeRenderProps,
  type ToggleButtonProps,
  ToggleGroupStateContext,
} from "react-aria-components";
import { tv, type VariantProps } from "tailwind-variants";
import { springLayout, transitionFor } from "./motion";
import { cn } from "./utils";
import { buttonLabel, touchTarget } from "./button-styles";
import { type Size, useSize } from "./size";

const toggleButtonStyles = tv({
  base: "inline-flex min-h-11 max-w-full shrink-0 cursor-pointer items-center justify-center gap-2 whitespace-nowrap rounded-md px-4 text-sm font-medium [&_svg:not([class*='size-'])]:size-4 outline-offset-4 outline-transparent transition-[color,background-color,border-color,box-shadow,scale,outline-color,outline-offset] duration-150 ease-out-quint motion-safe:pressed:scale-[0.96] disabled:cursor-default disabled:opacity-50 focus-visible:z-10 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring motion-reduce:outline-offset-2 [&_svg]:pointer-events-none [&_svg]:shrink-0",
  variants: {
    variant: {
      default:
        "border border-border bg-card text-foreground shadow-[var(--shadow-card)] hover:bg-muted pressed:bg-muted selected:border-primary/40 selected:bg-accent selected:text-accent-foreground",
      segmented:
        "border border-transparent bg-transparent px-3 text-muted-foreground shadow-none hover:bg-card/70 in-data-[item-highlight=under]:not-selected:hover:bg-transparent hover:text-foreground pressed:bg-card/70 selected:border-border selected:bg-card selected:text-foreground selected:shadow-[var(--shadow-card)]",
      ghost:
        "border border-transparent bg-transparent text-foreground hover:bg-muted in-data-[item-highlight=under]:not-selected:hover:bg-transparent pressed:bg-muted selected:bg-accent selected:text-accent-foreground",
    },
    size: {
      xs: `min-h-7 gap-1.5 rounded-sm px-2 text-xs [&_svg:not([class*='size-'])]:size-3.5 ${touchTarget}`,
      sm: `min-h-9 px-3 ${touchTarget}`,
      md: "min-h-11 px-4",
      lg: "min-h-12 px-5",
      xl: "min-h-14 gap-2.5 rounded-lg px-6 text-base [&_svg:not([class*='size-'])]:size-5",
    },
    adaptive: {
      true: "sm:min-h-9",
    },
    iconOnly: {
      true: "w-11 px-0 [&_svg:not([class*='size-'])]:size-4.5",
    },
  },
  compoundVariants: [
    {
      size: "xs",
      iconOnly: true,
      class: "w-7 [&_svg:not([class*='size-'])]:size-3.5",
    },
    {
      size: "sm",
      iconOnly: true,
      class: "w-9 [&_svg:not([class*='size-'])]:size-4",
    },
    {
      adaptive: true,
      iconOnly: true,
      class: "sm:w-9 sm:[&_svg:not([class*='size-'])]:size-4",
    },
    {
      size: "lg",
      iconOnly: true,
      class: "w-12 [&_svg:not([class*='size-'])]:size-5",
    },
    {
      size: "xl",
      iconOnly: true,
      class: "w-14 [&_svg:not([class*='size-'])]:size-6",
    },
  ],
  defaultVariants: { variant: "default" },
});

export interface ToggleButtonStyleProps extends ToggleButtonProps {
  variant?: NonNullable<VariantProps<typeof toggleButtonStyles>["variant"]>;
  size?: Size;
  iconOnly?: boolean;
}

export function ToggleButton({
  className,
  children,
  variant = "default",
  size: sizeProp,
  iconOnly = false,
  ...props
}: ToggleButtonStyleProps) {
  const reduceMotion = useReducedMotion();
  const size = useSize(sizeProp);
  const groupedSelection =
    useContext(ToggleGroupStateContext)?.selectionMode === "single" &&
    variant === "segmented";
  return (
    <AriaToggleButton
      {...props}
      data-slot="toggle-button"
      data-variant={variant}
      data-size={size}
      data-icon-only={iconOnly || undefined}
      className={composeRenderProps(className, (className) =>
        toggleButtonStyles({
          variant,
          size,
          adaptive: variant === "segmented" && !size,
          iconOnly,
          className: cn(
            groupedSelection &&
              "relative isolate selected:border-transparent selected:bg-transparent selected:shadow-none",
            className,
          ),
        }),
      )}
    >
      {composeRenderProps(children, (content, { isSelected }) => (
        <>
          {groupedSelection && isSelected && (
            <motion.span
              layoutId="toggle-group-selection"
              initial={false}
              aria-hidden="true"
              transition={transitionFor(reduceMotion, springLayout)}
              className="pointer-events-none absolute inset-0 -z-10 rounded-[inherit] border border-border bg-card shadow-[var(--shadow-card)] forced-colors:border-[Highlight]"
            />
          )}
          {buttonLabel(content)}
        </>
      ))}
    </AriaToggleButton>
  );
}
